<div class="page-heading"><div><span class="eyebrow">Parent · Hospital search</span><h1>Book a hospital</h1><p>Search active hospitals, check vaccine availability, and request a date.</p></div></div>
<?php if (!$children): ?><div class="toast toast-warning" role="status"><span>Add a child before requesting a hospital appointment.</span><a href="<?= e(url('parent.children')) ?>">Add child</a></div><?php endif; ?>
<form class="filter-bar" method="get" action="index.php"><input type="hidden" name="route" value="parent.hospitals"><label class="search-field"><span class="sr-only">Search hospitals</span><input name="search" value="<?= e($search) ?>" placeholder="Search by hospital, city, or address"><button type="submit">Search</button></label><?php if ($search): ?><a href="<?= e(url('parent.hospitals')) ?>">Clear</a><?php endif; ?></form>
<section class="card-grid hospital-grid"><?php foreach ($hospitals as $hospital): ?><article class="info-card"><div class="card-top"><span class="initial-badge"><?= e(mb_strtoupper(mb_substr($hospital['name'], 0, 1))) ?></span><span class="status status-<?= $hospital['available_count'] ? 'available' : 'unavailable' ?>"><?= (int) $hospital['available_count'] ?> available</span></div><h2><?= e($hospital['name']) ?></h2><p><?= e($hospital['address']) ?>, <?= e($hospital['city']) ?></p><?php if ($hospital['location_details']): ?><p class="muted"><?= e($hospital['location_details']) ?></p><?php endif; ?><div class="vaccine-tags"><?php foreach (array_slice(array_filter(explode('||', (string) $hospital['available_vaccines'])), 0, 4) as $label): ?><span><?= e($label) ?></span><?php endforeach; ?><?php if ((int) $hospital['available_count'] > 4): ?><span>+<?= (int) $hospital['available_count'] - 4 ?> more</span><?php endif; ?><?php if (!(int) $hospital['available_count']): ?><span>No stock reported</span><?php endif; ?></div><button class="button button-full button-small" type="button" data-dialog-open="booking-<?= (int) $hospital['id'] ?>" <?= !$children || !(int) $hospital['available_count'] ? 'disabled' : '' ?>>Request appointment</button></article>
<dialog id="booking-<?= (int) $hospital['id'] ?>" class="dialog"><form method="post" action="<?= e(url('parent.booking.create')) ?>" data-validate><?= csrf_field() ?><input type="hidden" name="hospital_id" value="<?= (int) $hospital['id'] ?>"><div class="dialog-heading"><div><span class="eyebrow">Appointment request</span><h2><?= e($hospital['name']) ?></h2></div><button type="button" data-dialog-close aria-label="Close">×</button></div><div class="form-grid"><label>Child<select name="child_id" required><option value="">Choose child</option><?php foreach ($children as $child): ?><option value="<?= (int) $child['id'] ?>"><?= e($child['name']) ?></option><?php endforeach; ?></select></label><label>Vaccine<select name="vaccine_id" required><option value="">Choose available vaccine</option><?php $availableLabels = explode('||', (string) $hospital['available_vaccines']); foreach ($vaccines as $vaccine): $label = $vaccine['name'] . ' — ' . $vaccine['dose_label']; if (in_array($label, $availableLabels, true)): ?><option value="<?= (int) $vaccine['id'] ?>"><?= e($vaccine['name']) ?> · <?= e($vaccine['dose_label']) ?></option><?php endif; endforeach; ?></select></label><label>Preferred date<input type="date" name="appointment_date" min="<?= e(date('Y-m-d')) ?>" required></label><label>Preferred time<input type="time" name="appointment_time" min="08:00" max="18:00" required></label><label class="span-2">Reason <small>Optional</small><textarea name="reason" maxlength="300" rows="2" placeholder="Routine vaccination or relevant detail"></textarea></label></div><div class="note"><strong>What happens next?</strong><p>The administrator reviews this request. The hospital receives it only after approval.</p></div><button class="button button-full" type="submit">Send request</button></form></dialog><?php endforeach; ?><?php if (!$hospitals): ?><div class="empty-state compact"><h2>No matching hospitals</h2><p>Try another name, city, or address.</p></div><?php endif; ?></section>
